}

.current-session-badge {
    font-size: 0.75rem;
    background: #cfe2ff;
    color: #084298;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
    margin-left: 0.5rem;
}

/* Confirmation dialog overlay */
.confirm-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1060;
}

.confirm-dialog {
    background: #fff;
    border-radius: 10px;
    padding: 1.5rem;
    max-width: 400px;
    width: 90%;
