}

.radio-option {
    flex: 1;
    text-align: center;
}

.radio-option input {
    display: none;
}

.radio-option label {
    display: block;
    padding: 0.5rem 1rem;
    cursor: pointer;
    font-size: 0.9rem;
    border-right: 1px solid #ced4da;
    transition: background 0.15s, color 0.15s;
    color: #495057;
}

.radio-option:last-child label {
    border-right: none;
}

.radio-option input:checked + label {
    background: #0d6efd;
    color: #fff;
}

/* Preview area */
.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 1.25rem;
    margin-top: 1rem;
    max-width: 500px;
    transition: all 0.3s;
}

.preview-area.theme-dark {
    background: #212529;
    color: #e9ecef;
    border-color: #495057;
}

.preview-area.theme-light {
    background: #fff;
    color: #212529;
}

.preview-area.theme-system {
    background: #f8f9fa;
    color: #212529;
    border-style: dashed;
}

.preview-area.font-small {
    font-size: 0.8rem;
}

.preview-area.font-medium {
    font-size: 1rem;
}

.preview-area.font-large {
    font-size: 1.2rem;
}

.preview-area.compact .preview-item {
    padding: 0.15rem 0;
}

.preview-area .preview-item {
    padding: 0.4rem 0;
    transition: padding 0.2s;
}

.preview-label {
    font-size: 0.75em;
    opacity: 0.6;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 0.75rem;
}

/* Validation */
.field-error {
    color: #dc3545;
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

@using sv_7606b8ad173d4930b88a1fa2c9eafcdb.Services
@inject ISettingsService SettingsService

<div>
    <h2 class="settings-section-title">Profile</h2>
    <p class="settings-section-desc">Manage your personal information</p>

    @if (_loading)
    {
        <p>Loading…</p>
    }
    else
    {
        <div class="avatar-preview">
            <img src="@_avatarUrl" alt="Avatar" />
            <div>
                <div><strong>@_displayName</strong></div>
                <div class="avatar-url-display">@_avatarUrl</div>
            </div>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="_displayName" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="_email" />
        </div>

        <div class="form-group">
            <label for="avatarUrl">Avatar URL</label>
            <input id="avatarUrl" type="text" @bind="_avatarUrl" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="_bio"></textarea>
        </div>

        <div class="btn-group-actions">
            <button class="btn-primary-settings" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving…" : "Save Changes")
            </button>
            <button class="btn-secondary-settings" @onclick="Discard">Discard Changes</button>
        </div>
    }

    @if (_showToast)
    {
        <div class="toast-message">✓ Profile saved successfully</div>
    }
</div>

@code {
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    private UserProfile? _savedProfile;
    private bool _loading = true;
    private bool _saving;
    private bool _showToast;

    protected override async Task OnInitializedAsync()
    {
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile p)
    {
        _displayName = p.DisplayName;
        _email = p.Email;
        _avatarUrl = p.AvatarUrl;
        _bio = p.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _saving = false;
        _showToast = true;
        StateHasChanged();

        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showToast = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        if (_savedProfile is not null)
            ApplyProfile(_savedProfile);
    }
}

