                    </button>
                    @if (_settings?.LastPasswordChange is not null)
                    {
                        <p style="margin-top: 0.75rem; font-size: 0.85rem; color: #6c757d;">
                            Last changed: @_settings.LastPasswordChange.Value.ToString("MMM dd, yyyy 'at' h:mm tt")
                        </p>
                    }
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="toggle-row" style="max-width:550px;">
            <div>
                <div class="toggle-row-label">Two-Factor Authentication</div>
                <div class="toggle-row-desc">
                    <span class="status-indicator @(_twoFactorEnabled ? "status-enabled" : "status-disabled")">
                        @(_twoFactorEnabled ? "● Enabled" : "● Disabled")
                    </span>
                </div>
            </div>
            <label class="toggle-switch">
                <input type="checkbox" @bind="_twoFactorEnabled" />
                <span class="toggle-slider"></span>
            </label>
        </div>

        <!-- Active Sessions -->
        <h4 style="margin-top: 2rem;">Active Sessions</h4>
        @if (_settings!.Sessions.Count > 0)
        {
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _settings.Sessions)
                    {
                        var isCurrent = session == _settings.Sessions[0];
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrent)
                                {
                                    <span class="current-session-badge">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (!isCurrent)
                                {
                                    <button class="btn-danger-settings"
                                            @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        }
        else
        {
            <p style="color: #6c757d;">No active sessions.</p>
        }
    }

    @if (_showToast)
    {
        <div class="toast-message">@_toastMessage</div>
    }

    <!-- Revoke Confirmation Dialog -->
    @if (_sessionToRevoke is not null)
    {
        <div class="confirm-overlay" @onclick="CancelRevoke">
            <div class="confirm-dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                <div class="confirm-actions">
                    <button class="btn-secondary-settings" @onclick="CancelRevoke">Cancel</button>
                    <button class="btn-danger-settings" @onclick="ConfirmRevokeAsync">Revoke Session</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private SecuritySettings? _settings;
    private bool _twoFactorEnabled;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;

    private bool _loading = true;
    private bool _changingPassword;
    private bool _showToast;
    private string _toastMessage = "";
    private ActiveSession? _sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (_newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        _changingPassword = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _changingPassword = false;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        ShowToast("✓ Password updated successfully");
    }

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is null) return;

        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _sessionToRevoke = null;
        ShowToast("✓ Session revoked");
    }

    private void ShowToast(string message)
    {
        _toastMessage = message;
        _showToast = true;
        StateHasChanged();
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showToast = false;
        await InvokeAsync(StateHasChanged);
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

