{"file_text": "@using sv_7606b8ad173d4930b88a1fa2c9eafcdb.Services
@inject ISettingsService SettingsService

<div>
    <h2 class="settings-section-title">Appearance</h2>
    <p class="settings-section-desc">Customize the look and feel</p>

    @if (_loading)
    {
        <p>Loading…</p>
    }
    else
    {
        <!-- Theme -->
        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                @foreach (var theme in _themes)
                {
                    <div class="radio-option">
                        <input type="radio" id="theme-@theme" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <label for="theme-@theme">@theme</label>
                    </div>
                }
            </div>
        </div>

        <!-- Font Size -->
        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                @foreach (var size in _fontSizes)
                {
                    <div class="radio-option">
                        <input type="radio" id="font-@size" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <label for="font-@size">@size</label>
                    </div>
                }
            </div>
        </div>

        <!-- Language -->
        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="toggle-row" style="max-width:350px; margin-top:0.5rem;">
            <div>
                <div class="toggle-row-label">Compact Mode</div>
                <div class="toggle-row-desc">Reduce spacing throughout the UI</div>
            </div>
            <label class="toggle-switch">
                <input type="checkbox" @bind="_compactMode" />
                <span class="toggle-slider"></span>
            </label>
        </div>

        <!-- Live Preview -->
        <h4 style="margin-top: 1.5rem;">Preview</h4>
        <div class="preview-area theme-@(_theme.ToLowerInvariant()) font-@(_fontSize.ToLowerInvariant()) @(_compactMode ? "compact" : "")">
            <div class="preview-label">Live Preview — @_theme theme, @_fontSize font, @_language</div>
            <div class="preview-item"><strong>Dashboard</strong></div>
            <div class="preview-item">Welcome back! Here's your activity summary for the week.</div>
            <div class="preview-item" style="opacity: 0.7;">Last login: today at 9:42 AM</div>
            <div class="preview-item">
                <span style="margin-right:1rem;">📊 12 reports</span>
                <span style="margin-right:1rem;">💬 5 messages</span>
                <span>⚙️ 3 tasks</span>
            </div>
        </div>

        <div class="btn-group-actions">
            <button class="btn-primary-settings" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving…" : "Save")
            </button>
        </div>
    }

    @if (_showToast)
    {
        <div class="toast-message">✓ Appearance settings saved</div>
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private bool _loading = true;
    private bool _saving;
    private bool _showToast;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        _showToast = true;
        StateHasChanged();
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showToast = false;
        await InvokeAsync(StateHasChanged);
    }
}
