@using sv_7606b8ad173d4930b88a1fa2c9eafcdb.Services
@inject ISettingsService SettingsService

<div>
    <h2 class="settings-section-title">Profile</h2>
    <p class="settings-section-desc">Manage your personal information</p>

    @if (_loading)
    {
        <p>Loading…</p>
    }
    else
    {
        <div class="avatar-preview">
            <img src="@_avatarUrl" alt="Avatar" />
            <div>
                <div><strong>@_displayName</strong></div>
                <div class="avatar-url-display">@_avatarUrl</div>
            </div>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="_displayName" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="_email" />
        </div>

        <div class="form-group">
            <label for="avatarUrl">Avatar URL</label>
            <input id="avatarUrl" type="text" @bind="_avatarUrl" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="_bio"></textarea>
        </div>

        <div class="btn-group-actions">
            <button class="btn-primary-settings" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving…" : "Save Changes")
            </button>
            <button class="btn-secondary-settings" @onclick="Discard">Discard Changes</button>
        </div>
    }

    @if (_showToast)
    {
        <div class="toast-message">✓ Profile saved successfully</div>
    }
</div>

@code {
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    private UserProfile? _savedProfile;
    private bool _loading = true;
    private bool _saving;
    private bool _showToast;

    protected override async Task OnInitializedAsync()
    {
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile p)
    {
        _displayName = p.DisplayName;
        _email = p.Email;
        _avatarUrl = p.AvatarUrl;
        _bio = p.Bio;
    }

    private async Task SaveAsync()
    {
