@using sv_7606b8ad173d4930b88a1fa2c9eafcdb.Services
@inject ISettingsService SettingsService

<div>
    <h2 class="settings-section-title">Notifications</h2>
    <p class="settings-section-desc">Control how you receive notifications</p>

    @if (_loading)
    {
        <p>Loading…</p>
    }
    else
    {
        <div class="toggle-row">
            <div>
                <div class="toggle-row-label">Email Notifications</div>
                <div class="toggle-row-desc">Receive updates via email</div>
            </div>
            <label class="toggle-switch">
                <input type="checkbox" @bind="_emailNotifications" />
                <span class="toggle-slider"></span>
            </label>
        </div>

        <div class="toggle-row">
            <div>
                <div class="toggle-row-label">Push Notifications</div>
                <div class="toggle-row-desc">Receive push notifications on your devices</div>
            </div>
            <label class="toggle-switch">
                <input type="checkbox" @bind="_pushNotifications" />
                <span class="toggle-slider"></span>
            </label>
        </div>

        <div class="toggle-row">
            <div>
                <div class="toggle-row-label">Weekly Digest</div>
                <div class="toggle-row-desc">Get a weekly summary of activity</div>
            </div>
            <label class="toggle-switch">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span class="toggle-slider"></span>
            </label>
        </div>

        <h4 style="margin-top: 1.5rem;">Muted Channels</h4>
        <div class="channels-list">
            @foreach (var channel in _channels)
            {
                <div class="channel-item">
                    <label>
                        <input type="checkbox"
                               checked="@_mutedChannels.Contains(channel)"
                               @onchange="e => ToggleMute(channel, (bool)(e.Value ?? false))" />
                        <span>#@channel</span>
                    </label>
                    @if (_mutedChannels.Contains(channel))
                    {
                        <span class="channel-muted">Muted</span>
                    }
                </div>
            }
        </div>

        <div class="btn-group-actions">
            <button class="btn-primary-settings" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving…" : "Save Preferences")
            </button>
        </div>
    }

    @if (_showToast)
    {
        <div class="toast-message">✓ Notification preferences saved</div>
    }
</div>

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _channels = new();

    private bool _loading = true;
    private bool _saving;
    private bool _showToast;

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _channels = prefs.MutedChannels;
        // All channels start muted (they come from MutedChannels list)
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var prefs = new NotificationPrefs(
            _emailNotifications,
            _pushNotifications,
            _weeklyDigest,
            _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        _showToast = true;
        StateHasChanged();
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showToast = false;
        await InvokeAsync(StateHasChanged);
    }
}

